# Merge and avoid duplicates by english lowercased
seen = set(item["english"].lower() for item in entries)
for item in additional_words:
    if item["english"].lower() not in seen:
        entries.append(item)
        seen.add(item["english"].lower())

entries.sort(key=lambda x: x["english"].lower())

with open(base_path, "w", encoding="utf-8") as f:
    json.dump(entries, f, ensure_ascii=False, indent=2)

print(f"Total vocabulary words in database: {len(entries)}")
